import * as THREE from 'https://unpkg.com/three@0.161.0/build/three.module.js';
const dishes=[['Crisp ham & egg',199,'NON-VEG',['Eggs','Ham','Bread crumbs','Herbs'],'egg'],['Fried squid',219,'NON-VEG',['Squid','Flour','Spices','Lemon'],'squid'],['Chicken wrap',189,'NON-VEG',['Chicken','Tortilla','Lettuce','Tomato'],'wrap'],['Pan cake',149,'VEG',['Flour','Milk','Egg','Butter'],'pancake'],['Momos',159,'VEG',['Flour','Cabbage','Carrot','Spices'],'momos'],['Noodles',179,'VEG',['Noodles','Vegetables','Soy sauce','Garlic'],'noodles'],['Sushi',249,'NON-VEG',['Sushi rice','Nori','Fish','Cucumber'],'sushi'],['Burger',179,'NON-VEG',['Bun','Patty','Lettuce','Tomato'],'burger'],['Pizza',279,'VEG',['Pizza dough','Tomato sauce','Cheese','Herbs'],'pizza'],['French Fries',109,'VEG',['Potato','Oil','Salt'],'fries'],['Donut',99,'VEG',['Flour','Milk','Sugar','Glaze'],'donut'],['Chocolate Cake',149,'VEG',['Flour','Cocoa','Sugar','Chocolate'],'cake'],['Ice Cream',129,'VEG',['Milk','Cream','Sugar','Vanilla'],'icecream'],['Grilled Chicken',269,'NON-VEG',['Chicken','Yogurt','Ginger','Garlic'],'chicken']];
const colors=['#eee5ff','#ffdbbf','#fbf0ce','#cde8d3'];let page=0;const menu=document.querySelector('#menu'),dialog=document.querySelector('#viewer');
function draw(){menu.innerHTML='';dishes.slice(page*7,page*7+7).forEach((dish,n)=>{const [name,,type]=dish,b=document.createElement('button');b.className='card';b.style.background=colors[(n+page)%colors.length];b.innerHTML=`<small>${String(page*7+n+1).padStart(2,'0')}</small><h2>${name}</h2><small>${type}</small><i class="dot"></i>`;b.onclick=()=>openDish(dish);menu.append(b)});document.querySelector('#page-label').textContent=`0${page+1} / 02`}draw();document.querySelector('#next').onclick=()=>{page=(page+1)%2;draw()};document.querySelector('#previous').onclick=()=>{page=(page+1)%2;draw()};
document.querySelector('#camera-toggle').onclick=async()=>{try{const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});document.querySelector('#camera').srcObject=stream;document.body.classList.add('camera-on')}catch{alert('Camera access was not granted. You can still explore the 3D menu.')}};
let renderer,scene,camera,food,down,px,py;function init3d(){const canvas=document.querySelector('#model');renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));scene=new THREE.Scene();camera=new THREE.PerspectiveCamera(38,1,.1,100);camera.position.set(0,2.7,7);scene.add(new THREE.HemisphereLight(0xfff5d8,0x1e4c40,3));const key=new THREE.DirectionalLight(0xffc880,3);key.position.set(4,6,5);scene.add(key);const plate=new THREE.Mesh(new THREE.CylinderGeometry(2.55,.14,48),new THREE.MeshStandardMaterial({color:0xf6edd9,roughness:.55}));plate.position.y=-1.15;scene.add(plate);canvas.onpointerdown=e=>{down=true;px=e.clientX;py=e.clientY;canvas.setPointerCapture(e.pointerId)};canvas.onpointermove=e=>{if(!down||!food)return;food.rotation.y+=(e.clientX-px)*.014;food.rotation.x+=(e.clientY-py)*.008;px=e.clientX;py=e.clientY};canvas.onpointerup=()=>down=false;canvas.onwheel=e=>camera.position.z=Math.max(4,Math.min(10,camera.position.z+e.deltaY*.007));function frame(){requestAnimationFrame(frame);const r=canvas.getBoundingClientRect();renderer.setSize(r.width,r.height,false);camera.aspect=r.width/r.height;camera.updateProjectionMatrix();renderer.render(scene,camera)}frame()}
const mat=c=>new THREE.MeshStandardMaterial({color:c,roughness:.55}),add=(g,m,p=[0,0,0])=>{const x=new THREE.Mesh(g,mat(m));x.position.set(...p);food.add(x);return x};function makeFood(kind){if(food)scene.remove(food);food=new THREE.Group();scene.add(food);if(kind==='pizza'||kind==='pancake'){[0,.22,.44].forEach((y,i)=>add(new THREE.CylinderGeometry(1.65,.18,40),i===2?0xf4c94e:0xd89442,[0,y,0]));if(kind==='pizza')for(let i=0;i<7;i++)add(new THREE.SphereGeometry(.18,16,12),0xbc2d20,[Math.cos(i)*.9,.62,Math.sin(i)*.9])}else if(kind==='burger'){add(new THREE.SphereGeometry(1.3,32,16,0,Math.PI*2,0,Math.PI/2),0xe0a152,[0,.55,0]);add(new THREE.CylinderGeometry(1.15,.22,32),0x4a2716,[0,.13,0]);add(new THREE.CylinderGeometry(1.24,.08,32),0xf0b82d,[0,-.15,0]);add(new THREE.CylinderGeometry(1.18,.2,32),0xe0a152,[0,-.4,0])}else if(kind==='donut'){add(new THREE.TorusGeometry(1,.38,22,46),0xf1aa9e,[0,.1,0])}else if(kind==='sushi'){for(let i=0;i<5;i++){let a=i*1.26;add(new THREE.CylinderGeometry(.42,.55,24),0xeee5d3,[Math.cos(a)*1.1,0,Math.sin(a)*1.1]);add(new THREE.CylinderGeometry(.25,.57,24),i%2?0xf08068:0x6aa663,[Math.cos(a)*1.1,.04,Math.sin(a)*1.1])}}else if(kind==='icecream'){add(new THREE.ConeGeometry(.85,1.9,4),0xc98950,[0,-.18,0]);add(new THREE.SphereGeometry(.95,32,20),0xf2d5a6,[0,1.0,0])}else{const c=kind==='chicken'?0xb45b22:kind==='noodles'?0xe8c25d:0xedc799;add(new THREE.SphereGeometry(1.25,32,22),c,[0,.15,0]);for(let i=0;i<5;i++)add(new THREE.SphereGeometry(.28,16,12),kind==='wrap'?0x5d9d56:0xdf7144,[Math.cos(i*1.25)*.72,.75,Math.sin(i*1.25)*.72])}}
function openDish(dish){const [name,price,type,ingredients,kind]=dish;document.querySelector('#dish-name').textContent=name;document.querySelector('#dish-type').textContent=type+' • INTERACTIVE 3D PREVIEW';document.querySelector('#dish-price').textContent='₹ '+price;document.querySelector('#ingredients').innerHTML=ingredients.map(i=>`<li>${i}</li>`).join('');dialog.showModal();if(!renderer)init3d();makeFood(kind)}document.querySelector('#close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});
